let activeCount = 0;
const idleWaiters = new Set();

const isIdle = () => activeCount === 0 && queue.size === 0;

const settleWaiter = waiter => {
	waiter.signal?.removeEventListener('abort', waiter.onAbort);
	idleWaiters.delete(waiter);
};

const notifyIdle = () => {
	if (isIdle() && idleWaiters.size > 0) {
		const waiters = [...idleWaiters];

		for (const waiter of waiters) {
			settleWaiter(waiter);
			waiter.resolve();
		}
	}
};

