onIdle: {
	value(options = {}) {
		const {signal} = options;

		if (signal !== undefined && !(signal instanceof AbortSignal)) {
			throw new TypeError('Expected `signal` to be an AbortSignal');
		}

		return new Promise((resolve, reject) => {
			if (signal?.aborted) {
				reject(signal.reason);
				return;
			}

			const waiter = {resolve, reject, signal, onAbort: undefined};

			if (signal) {
				waiter.onAbort = () => {
					// Aborting only rejects this waiter; running jobs and other
					// waiters are unaffected.
					settleWaiter(waiter);
					reject(signal.reason);
				};

				signal.addEventListener('abort', waiter.onAbort, {once: true});
			}

			idleWaiters.add(waiter);
			// Defer so that any work scheduled in the current synchronous
			// sequence is enqueued before idle is reported.
			queueMicrotask(notifyIdle);
		});
	},
},

