import test from 'ava';
import pLimit, {limitFunction} from './index.js';

const watchIdle = (limiter, options) => {
	const state = {idle: false, error: undefined};
	const promise = (async () => {
		try {
			await limiter.onIdle(options);
			state.idle = true;
		} catch (error) {
			state.error = error;
		}
	})();

	return {state, promise};
};

test('onIdle rejects with signal.reason when aborted', async t => {
	const limit = pLimit(1);
	const controller = new AbortController();
	const reason = new Error('🦄');

	const {state, promise} = watchIdle(limit, {signal: controller.signal});

	limit(async () => {
		await delay(50);
	});

	controller.abort(reason);

	await promise;
	t.is(state.error, reason);
	t.false(state.idle);
});

test('onIdle with an already-aborted signal rejects even when idle', async t => {
	const limit = pLimit(1);
	const reason = new Error('already aborted');
	const controller = new AbortController();
	controller.abort(reason);

	await t.throwsAsync(limit.onIdle({signal: controller.signal}), {is: reason});
});

test('onIdle with an already-aborted signal rejects even while busy', async t => {
	const limit = pLimit(1);
	const reason = new Error('already aborted');
	const controller = new AbortController();
	controller.abort(reason);

	const job = limit(async () => {
		await delay(20);
	});

	await t.throwsAsync(limit.onIdle({signal: controller.signal}), {is: reason});
	await job;
});

test('aborting one waiter does not affect other waiters', async t => {
	const limit = pLimit(1);
	const controller = new AbortController();
	const reason = new Error('🦄');

	const aborted = watchIdle(limit, {signal: controller.signal});
	const surviving = watchIdle(limit);

	const job = limit(async () => {
		await delay(40);
	});

	controller.abort(reason);

	await aborted.promise;
	t.is(aborted.state.error, reason);

	await Promise.all([job, surviving.promise]);
	t.true(surviving.state.idle);
});

test('aborting onIdle does not cancel running or queued jobs', async t => {
	const limit = pLimit(1);
	const controller = new AbortController();
	const order = [];

	const first = limit(async () => {
